<?php $pageTitle='Coupon Management';require '../includes/admin-header.php';$pdo=db();if($_SERVER['REQUEST_METHOD']==='POST'){$pdo->prepare('INSERT INTO coupons(code,discount_type,discount_value,minimum_order,maximum_discount,expiry_date,usage_limit,status) VALUES(?,?,?,?,?,?,?,?)')->execute([strtoupper(trim($_POST['code'])),$_POST['discount_type'],(float)$_POST['discount_value'],(float)$_POST['minimum_order'],$_POST['maximum_discount']?:null,$_POST['expiry_date'],(int)$_POST['usage_limit'],$_POST['status']]);flash('success','Coupon created.');go('admin/coupons.php');}if(($_GET['action']??'')==='toggle'){$pdo->prepare("UPDATE coupons SET status=IF(status='active','inactive','active') WHERE id=?")->execute([(int)$_GET['id']]);go('admin/coupons.php');}$coupons=$pdo->query('SELECT * FROM coupons ORDER BY expiry_date DESC')->fetchAll(); ?><div class="row g-4"><div class="col-lg-4"><form method="post" class="card card-body"><h5>Add coupon</h5><input class="form-control mb-2" name="code" placeholder="Coupon code" required><div class="row g-2"><div class="col"><select class="form-select" name="discount_type"><option value="percent">Percent</option><option value="flat">Flat</option></select></div><div class="col"><input class="form-control" name="discount_value" placeholder="Value" required></div></div><input class="form-control my-2" name="minimum_order" placeholder="Minimum order" value="0"><input class="form-control mb-2" name="maximum_discount" placeholder="Maximum discount"><input class="form-control mb-2" type="date" name="expiry_date" required><input class="form-control mb-2" name="usage_limit" value="100"><select class="form-select mb-3" name="status"><option value="active">Active</option><option value="inactive">Inactive</option></select><button class="btn btn-dark">Create coupon</button></form></div><div class="col-lg-8"><div class="card table-responsive"><table class="table mb-0"><thead><tr><th>Code</th><th>Discount</th><th>Min</th><th>Expires</th><th>Use</th><th>Status</th><th></th></tr></thead><tbody><?php foreach($coupons as $c): ?><tr><td><b><?=e($c['code'])?></b></td><td><?=$c['discount_value']?> <?=$c['discount_type']?></td><td><?=money($c['minimum_order'])?></td><td><?=$c['expiry_date']?></td><td><?=$c['used_count']?>/<?=$c['usage_limit']?></td><td><?=e($c['status'])?></td><td><a href="coupons.php?action=toggle&id=<?=$c['id']?>" class="btn btn-sm btn-outline-dark">Toggle</a></td></tr><?php endforeach ?></tbody></table></div></div></div><?php require '../includes/admin-footer.php'; ?>
